'''
A sample script to seed initial data into the application.

This script can be extended to insert sample data into databases or other storage systems.

Example usage:
    python scripts/seed_data.py
'''

# Import necessary modules
import os
import sys

# Define the data to be seeded
SEED_DATA = {
    'users': [
        {'id': 1, 'name': 'John Doe', 'email': 'john@example.com'},
        {'id': 2, 'name': 'Jane Smith', 'email': 'jane@example.com'}
    ],
    'products': [
        {'id': 101, 'name': 'Laptop', 'price': 1000},
        {'id': 102, 'name': 'Mouse', 'price': 25}
    ]
}

# Function to seed data
def seed_data():
    print("Seeding data...")
    for data_type, data_list in SEED_DATA.items():
        print(f"Seeding {data_type}: {len(data_list)} items")
        for item in data_list:
            print(f"  - {item}")

if __name__ == "__main__":
    seed_data()
